package cn.zhuatech.supplyai;
import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import java.util.regex.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class SupplyAiApiIntegrationTests{@Autowired MockMvc mvc;String token;@BeforeEach void login()throws Exception{String j=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"operator\",\"password\":\"Demo@2026\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();Matcher m=Pattern.compile("\\\"token\\\":\\\"([^\\\"]+)\\\"").matcher(j);if(!m.find())throw new AssertionError();token=m.group(1);}@Test void assessesCriticalSupplier()throws Exception{mvc.perform(post("/api/ai/supply/assess").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"supplierCode\":\"SUP-AX17\",\"onTimeDeliveryRate\":68,\"qualityPassRate\":91,\"leadTimeDays\":62,\"countryRiskScore\":74,\"singleSourceDependencyPercent\":88,\"inventoryCoverageDays\":6}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.riskLevel").value("CRITICAL"));}@Test void deniesAnonymous()throws Exception{mvc.perform(post("/api/ai/supply/assess").contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isForbidden());}}
